using Shop;

public class PriceCalculatorTests
{
    private static Order OrderOf(CustomerType customer) =>
        new(customer, [new OrderLine("A", 100m, 2), new OrderLine("B", 50m, 1)]);

    private static Order OrderWithSubtotal(CustomerType customer, decimal subtotal) =>
        new(customer, [new OrderLine("A", subtotal, 1)]);

    [Fact]
    public void Regular_customer_pays_the_subtotal() =>
        Assert.Equal(250m, PriceCalculator.Total(OrderOf(CustomerType.Regular)));

    [Fact]
    public void Loyal_customer_gets_five_percent_off() =>
        Assert.Equal(237.50m, PriceCalculator.Total(OrderOf(CustomerType.Loyal)));

    [Fact]
    public void Student_gets_ten_percent_off_below_the_cap() =>
        Assert.Equal(225m, PriceCalculator.Total(OrderOf(CustomerType.Student)));

    [Fact]
    public void Student_discount_at_the_cap_is_exactly_thirty() =>
        Assert.Equal(270m, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Student, 300m)));

    [Fact]
    public void Student_discount_never_exceeds_thirty() =>
        Assert.Equal(970m, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Student, 1_000m)));

    [Fact]
    public void Partner_gets_ten_percent_off_up_to_one_thousand() =>
        Assert.Equal(225m, PriceCalculator.Total(OrderOf(CustomerType.Partner)));

    [Fact]
    public void Partner_gets_ten_percent_off_at_exactly_one_thousand() =>
        Assert.Equal(900m, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Partner, 1_000m)));

    [Fact]
    public void Partner_gets_fifteen_percent_off_the_whole_order_above_one_thousand() =>
        Assert.Equal(1_700m, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Partner, 2_000m)));

    [Theory]
    [InlineData(CustomerType.Regular, "Regular: no discount")]
    [InlineData(CustomerType.Loyal, "Loyal: 5% off")]
    [InlineData(CustomerType.Student, "Student: 10% off, max 30")]
    [InlineData(CustomerType.Partner, "Partner: 10% off, 15% above 1,000")]
    public void Receipt_shows_the_discount_as_one_line(CustomerType customer, string expected) =>
        Assert.Equal(expected, PriceCalculator.Receipt(OrderOf(customer)).DiscountLine);

    [Fact]
    public void Receipt_carries_subtotal_discount_and_total()
    {
        var receipt = PriceCalculator.Receipt(OrderWithSubtotal(CustomerType.Student, 500m));

        Assert.Equal(500m, receipt.Subtotal);
        Assert.Equal(30m, receipt.Discount);
        Assert.Equal(470m, receipt.Total);
    }

    [Fact]
    public void Every_customer_type_has_a_discount_strategy()
    {
        foreach (var customer in Enum.GetValues<CustomerType>())
        {
            var strategy = DiscountStrategies.For(customer);
            Assert.False(string.IsNullOrWhiteSpace(strategy.Description));
        }
    }
}

